--
-- Triggers `pd_field_history`
--
DELIMITER $$
CREATE TRIGGER `pd_field_history_no_delete` BEFORE DELETE ON `pd_field_history` FOR EACH ROW SIGNAL SQLSTATE '45000'
  SET MESSAGE_TEXT = 'pd_field_history is append-only: a record of what something used to say cannot be removed.'
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `pd_field_history_no_update` BEFORE UPDATE ON `pd_field_history` FOR EACH ROW SIGNAL SQLSTATE '45000'
  SET MESSAGE_TEXT = 'pd_field_history is append-only: a record of what something used to say cannot be changed.'
$$
DELIMITER ;

